## Required vs Optional Parameters

In TJS, the punctuation tells you everything:

| Syntax | Meaning |
|--------|---------|
| `param: 'value'` | **Required** - must be provided |
| `param = 'value'` | **Optional** - defaults to value |

The example value after `:` or `=` defines the type.
#/
test 'requires name and email' {
  const user = createUser('Alice', 'alice@test.com')
  expect(user.name).toBe('Alice')
  expect(user.age).toBe(0) // default
}

function createUser(
  name: 'anonymous',
  email: 'user@example.com',
  age = 0,
  admin = false
): { name: 'anonymous', email: 'user@example.com', age: 0, admin: false } {
  return { name, email, age, admin }
}

// Check the metadata
console.log('Params:', createUser.__tjs.params)
createUser('Alice', 'alice@example.com')

// The key insight: TS types become runtime checks

function divide(a: number, b: number): number {
  if (b === 0) return NaN
  return a / b
}

// Valid calls work normally
console.log('10 / 2 =', divide(10, 2))
console.log('10 / 0 =', divide(10, 0))

// Invalid calls return error objects (not crashes!)
const badResult = divide('ten' as any, 2)
console.log('divide("ten", 2) =', badResult)

if (badResult instanceof Error) {
  console.log('  ^ This is a MonadicError, not a crash!')
  console.log('  message:', badResult.message)
